public static Pcm decode(byte[] ogg) throws IOException {
        InputStream input = new ByteArrayInputStream(ogg);
        ByteArrayOutputStream out = new ByteArrayOutputStream(
                (int) Math.max(64, Math.min((long) ogg.length * 4, 1 << 26)));   // cap initial guess at 64 MiB

        SyncState oy = new SyncState();
        StreamState os = new StreamState();
        Page og = new Page();
        Packet op = new Packet();
        Info vi = new Info();
        Comment vc = new Comment();
        DspState vd = new DspState();
        Block vb = new Block(vd);

        try {
        byte[] buffer;
        int bytes;
        oy.init();

        // ---- first page / first header packet ----
        int index = oy.buffer(4096);
        buffer = oy.data;
        bytes = readSome(input, buffer, index, 4096);
        oy.wrote(bytes);

        if(oy.pageout(og) != 1)
            throw new IOException("not an Ogg bitstream");

        os.init(og.serialno());
        vi.init();
        vc.init();
        if(os.pagein(og) < 0)
            throw new IOException("error reading first Ogg page");
        if(os.packetout(op) != 1)
            throw new IOException("error reading initial header packet");
        if(vi.synthesis_headerin(vc, op) < 0)
            throw new IOException("not Vorbis audio data");

        // ---- remaining two header packets ----
        int i = 0;
        while(i < 2) {
            while(i < 2) {
                int result = oy.pageout(og);
                if(result == 0)
                    break;
                if(result == 1) {
                    os.pagein(og);
                    while(i < 2) {
                        result = os.packetout(op);
                        if(result == 0)
                            break;
                        if(result == -1 || vi.synthesis_headerin(vc, op) < 0)
                            throw new IOException("corrupt secondary Vorbis header");
                        i++;
                    }
                }
            }
            index = oy.buffer(4096);
            buffer = oy.data;
            bytes = readSome(input, buffer, index, 4096);
            if(bytes == 0 && i < 2)
                throw new IOException("end of file before all Vorbis headers");
            oy.wrote(bytes);
        }

        int rate = vi.rate;
        int channels = vi.channels;
        if(channels < 1 || rate < 1)
            throw new IOException("invalid Vorbis stream (rate=" + rate + ", channels=" + channels + ")");

        int convsize = 4096 / channels;
        byte[] convbuffer = new byte[convsize * 2 * channels];

        vd.synthesis_init(vi);
        vb.init(vd);

        float[][][] pcmf = new float[1][][];
        int[] pcmIndex = new int[channels];

        boolean eos = false;
        while(!eos) {
            while(!eos) {
                int result = oy.pageout(og);
                if(result == 0)
                    break;          // need more data
                if(result != -1) {  // -1 == hole in data; skip but keep going
                    os.pagein(og);
                    while(true) {
                        result = os.packetout(op);
                        if(result == 0)
                            break;
                        if(result == -1)
                            continue;
                        if(vb.synthesis(op) == 0)
                            vd.synthesis_blockin(vb);
                        int samples;
                        while((samples = vd.synthesis_pcmout(pcmf, pcmIndex)) > 0) {
                            float[][] pcm = pcmf[0];
                            int bout = Math.min(samples, convsize);
                            for(int ch = 0; ch < channels; ch++) {
                                int ptr = ch * 2;
                                int mono = pcmIndex[ch];
                                for(int j = 0; j < bout; j++) {
                                    int val = (int) (pcm[ch][mono + j] * 32767.0);
                                    if(val > 32767)  val = 32767;
                                    if(val < -32768) val = -32768;
                                    if(val < 0)      val = val | 0x8000;
                                    convbuffer[ptr] = (byte) val;
                                    convbuffer[ptr + 1] = (byte) (val >>> 8);
                                    ptr += 2 * channels;
                                }
                            }
                            out.write(convbuffer, 0, 2 * channels * bout);
                            vd.synthesis_read(bout);
                        }
                    }
                    if(og.eos() != 0)
                        eos = true;
                }
            }
            if(!eos) {
                index = oy.buffer(4096);
                buffer = oy.data;
                bytes = readSome(input, buffer, index, 4096);
                oy.wrote(bytes);
                if(bytes == 0)
                    eos = true;
            }
        }

        return new Pcm(out.toByteArray(), rate, channels);
        } finally {
            os.clear();
            vb.clear();
            vd.clear();
            vi.clear();
            oy.clear();
        }
    }

public static String summary(Layer l) {
        try {
            switch(l.name) {
                case "image": {
                    ImageInfo ii = ImageInfo.parse(l.data);
                    String fmt = ii.imageFormat != null ? ii.imageFormat : "image";
                    return ii.recognized ? "id=" + ii.id + "  " + fmt : fmt;
                }
                case "tex": {
                    TexInfo ti = TexInfo.parse(l.data);
                    if(!ti.found)
                        return "texture";
                    return (ti.recognized ? "id=" + ti.id + "  " : "")
                            + ti.szX + "x" + ti.szY + " " + ti.imageFormat;
                }
                case "audio2": {
                    AudioInfo ai = AudioInfo.parse(l.data);
                    if(ai.format == null)
                        return "audio";
                    return (ai.recognized && !ai.id.isEmpty() ? "\"" + ai.id + "\" " : "") + "Ogg Vorbis";
                }
                case "font": {
                    FontInfo fi = FontInfo.parse(l.data);
                    return fi.format != null ? fi.format.toUpperCase() + " font" : "font";
                }
                case "tooltip":
                case "pagina": {
                    String text = editableText(l);
                    return text != null
                            ? "\"" + preview(text, 30) + "\""
                            : "invalid UTF-8 (raw)";
                }
                case "action": {
                    java.util.Map<String, Object> m = ActionCodec.decode(l.data);
                    return "\"" + m.get("name") + "\"";
                }
                case "props": {
                    java.util.Map<String, Object> m = PropsCodec.decode(l.data);
                    @SuppressWarnings("unchecked")
                    java.util.Map<String, Object> p = (java.util.Map<String, Object>) m.get("props");
                    return p.size() + " propert" + (p.size() == 1 ? "y" : "ies");
                }
                case "vbuf2": {
                    Vbuf2Info vi = Vbuf2Info.parse(l.data);
                    return vi.recognized ? vi.num + " vertices" : "vertex buffer";
                }
                case "mesh": {
                    MeshInfo mi = MeshInfo.parse(l.data);
                    return mi.recognized ? mi.numTris + " triangles" : "mesh";
                }
                case "tile": {
                    TileInfo ti = TileInfo.parse(l.data);
                    if(!ti.recognized)
                        return "terrain tile";
                    return ti.kindName() + " id=" + ti.id
                            + (ti.imageFormat != null ? " " + ti.imageFormat : "");
                }
                case "tileset2": {
                    TilesetInfo ti = TilesetInfo.parse(l.data);
                    if(!ti.recognized)
                        return "tileset";
                    return "tiler \"" + (ti.tilerName != null ? ti.tilerName : "?") + "\""
                            + (ti.flavors.isEmpty() ? "" : ", " + ti.flavors.size() + " flavor");
                }
                case "flavobj": {
                    FlavObjInfo fo = FlavObjInfo.parse(l.data);
                    return fo.recognized ? fo.res : "flavor object";
                }
                case "mat2": {
                    java.util.Map<String, Object> m = Mat2Codec.decode(l.data);
                    java.util.List<?> es = (java.util.List<?>) m.get("entries");
                    return es.size() + " material command" + (es.size() == 1 ? "" : "s");
                }
                case "code": {
                    CodeInfo ci = CodeInfo.parse(l.data);
                    if(!ci.recognized)
                        return "code";
                    int dot = ci.name.lastIndexOf('.');
                    return (dot >= 0 ? ci.name.substring(dot + 1) : ci.name) + ".class";
                }
                case "anim": {
                    java.util.Map<String, Object> m = AnimCodec.decode(l.data);
                    java.util.List<?> fr = (java.util.List<?>) m.get("frames");
                    return fr.size() + " frames @ " + m.get("delay") + "ms";
                }
                case "neg": {
                    java.util.Map<String, Object> m = NegCodec.decode(l.data);
                    java.util.List<?> c = (java.util.List<?>) m.get("center");
                    java.util.List<?> eps = (java.util.List<?>) m.get("endpoints");
                    return "click (" + c.get(0) + "," + c.get(1) + "), " + eps.size() + " endpoint grp";
                }
                case "obst": {
                    java.util.Map<String, Object> m = ObstCodec.decode(l.data);
                    java.util.List<?> polys = (java.util.List<?>) m.get("polygons");
                    int pts = 0;
                    for(Object p : polys)
                        pts += ((java.util.List<?>) p).size();
                    return polys.size() + " polygon" + (polys.size() == 1 ? "" : "s") + ", " + pts + " pts";
                }
                case "codeentry": {
                    CodeEntryInfo ce = CodeEntryInfo.parse(l.data);
                    return ce.entries.size() + " entry pt" + (ce.entries.size() == 1 ? "" : "s")
                            + ", " + ce.classpath.size() + " dep" + (ce.classpath.size() == 1 ? "" : "s");
                }
                case "deps": {
                    DepsInfo di = DepsInfo.parse(l.data);
                    if(!di.recognized)
                        return "dependencies";
                    return di.deps.size() + " dependenc" + (di.deps.size() == 1 ? "y" : "ies");
                }
                case "rlink": {
                    RLinkInfo ri = RLinkInfo.parse(l.data);
                    if(!ri.recognized && ri.links.isEmpty())
                        return "resource links";
                    return ri.links.size() + " link" + (ri.links.size() == 1 ? "" : "s");
                }
                case "src": {
                    SrcInfo si = SrcInfo.parse(l.data);
                    return si.recognized ? si.fileName : "source file";
                }
                case "light": {
                    LightInfo li = LightInfo.parse(l.data);
                    return li.recognized ? li.kind() : "light";
                }
                case "skel": {
                    SkelInfo si = SkelInfo.parse(l.data);
                    if(!si.recognized)
                        return "skeleton";
                    return si.bones.size() + " bone" + (si.bones.size() == 1 ? "" : "s");
                }
                case "skan": {
                    SkanInfo si = SkanInfo.parse(l.data);
                    if(!si.recognized)
                        return "animation";
                    return si.tracks.size() + " track" + (si.tracks.size() == 1 ? "" : "s")
                            + ", " + trim(si.len) + "s " + si.mode;
                }
                case "boneoff": {
                    BoneOffInfo bo = BoneOffInfo.parse(l.data);
                    if(!bo.recognized)
                        return "equip point";
                    return "\"" + bo.name + "\"  " + bo.ops.size() + " op" + (bo.ops.size() == 1 ? "" : "s");
                }
                case "manim": {
                    MeshAnimInfo mi = MeshAnimInfo.parse(l.data);
                    if(!mi.recognized)
                        return "mesh animation";
                    return mi.frames.size() + " frame" + (mi.frames.size() == 1 ? "" : "s")
                            + ", " + trim(mi.len) + "s";
                }
                default:
                    return l.data.length + " bytes";
            }
        } catch(RuntimeException e) {
            return l.data.length + " bytes";
        }
    }

public static Export export(Layer l) {
        switch(l.name) {
            case "image": {
                byte[] img = embeddedImage(l);
                if(img != null) {
                    String e = ImageInfo.parse(l.data).imageFormat;
                    return new Export(img, e, e.toUpperCase() + " image");
                }
                break;
            }
            case "tex": {
                byte[] img = embeddedImage(l);
                if(img != null) {
                    String e = TexInfo.parse(l.data).imageFormat;
                    return new Export(img, e, e.toUpperCase() + " texture");
                }
                break;
            }
            case "tile": {
                byte[] img = embeddedImage(l);
                if(img != null) {
                    String e = TileInfo.parse(l.data).imageFormat;
                    return new Export(img, e, e.toUpperCase() + " terrain tile");
                }
                break;
            }
            case "audio2": {
                AudioInfo ai = AudioInfo.parse(l.data);
                if(ai.format != null)
                    return new Export(Arrays.copyOfRange(l.data, ai.audioOffset, l.data.length),
                            "ogg", "Ogg Vorbis audio");
                break;
            }
            case "font": {
                FontInfo fi = FontInfo.parse(l.data);
                if(fi.format != null)
                    return new Export(Arrays.copyOfRange(l.data, fi.fontOffset, l.data.length),
                            fi.format, fi.format.toUpperCase() + " font");
                break;
            }
            case "midi":
                return new Export(l.data.clone(), "mid", "MIDI music");
            case "tooltip":
            case "pagina":
                return new Export(l.data.clone(), "txt", "Text");
            case "props": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "action": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "mat2": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "anim": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "neg": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "obst": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "boneoff": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "light": {
                String j = editableJson(l);
                if(j != null)
                    return new Export(j.getBytes(StandardCharsets.UTF_8), "json", "JSON");
                break;
            }
            case "code": {
                CodeInfo ci = CodeInfo.parse(l.data);
                if(ci.recognized && ci.code != null)
                    return new Export(ci.code, "class", "Java class file");
                break;
            }
            case "src": {
                SrcInfo si = SrcInfo.parse(l.data);
                if(si.recognized) {
                    String ext = extensionOf(si.fileName, "java");
                    return new Export(si.source, ext, "Source file");
                }
                break;
            }
            case "deps":
            case "rlink": {
                String t = referenceText(l);
                if(t != null)
                    return new Export(t.getBytes(StandardCharsets.UTF_8), "txt", "Reference listing");
                break;
            }
            default:
                break;
        }
        return new Export(l.data.clone(), "bin", "Raw bytes");
    }

public static Result toGlb(ResContainer modelRes, ResContainer skeletonRes,
                               ResContainer animationRes, String sourceName) {
        Map<Integer, Vbuf2Data> vbufs = new LinkedHashMap<>();
        for(Layer l : modelRes.layers)
            if(l.name.equals("vbuf2")) {
                Vbuf2Data d = Vbuf2Data.parse(l.data);
                if(d != null)
                    vbufs.putIfAbsent(d.id, d);
            }
        List<MeshInfo> meshes = new ArrayList<>();
        for(Layer l : modelRes.layers)
            if(l.name.equals("mesh")) {
                MeshInfo mi = MeshInfo.parse(l.data);
                if(mi.recognized && mi.indices != null)
                    meshes.add(mi);
            }

        List<TexMat> texMats = collectTextures(modelRes);
        Map<Integer, Integer> texIds = collectTexIds(modelRes);
        Map<Integer, Integer> matToTex = collectMatToTex(modelRes, texIds);

        // Modern mesh metadata can distinguish layers that share a matid (notably
        // alternate "ref" parts). Give each modern layer its own stable material
        // identity so Blender does not merge those headers away.
        List<MeshMaterial> gltfMaterials = new ArrayList<>();
        List<Integer> meshMaterials = new ArrayList<>();
        Map<Integer, Integer> legacyMaterials = new LinkedHashMap<>();
        for(int i = 0; i < meshes.size(); i++) {
            MeshInfo m = meshes.get(i);
            int material;
            if(m.modern) {
                material = gltfMaterials.size();
                gltfMaterials.add(new MeshMaterial(m.matid, "rfmat_" + m.matid + "_mesh_" + i));
            } else {
                Integer existing = legacyMaterials.get(m.matid);
                if(existing == null) {
                    existing = gltfMaterials.size();
                    legacyMaterials.put(m.matid, existing);
                    gltfMaterials.add(new MeshMaterial(m.matid, "rfmat_" + m.matid));
                }
                material = existing;
            }
            meshMaterials.add(material);
        }

        // Unified joint list starts with every bone-bearing vbuf's influences
        // (JOINTS_0 is later remapped from a vbuf's local order to this).
        List<String> joints = new ArrayList<>();
        for(Vbuf2Data d : vbufs.values())
            if(d.boneNames != null)
                for(String n : d.boneNames)
                    if(!joints.contains(n))
                        joints.add(n);
        SkelInfo skel = firstSkel(skeletonRes);               // bind skeleton, or null
        boolean composite = modelRes != animationRes || skeletonRes != animationRes;
        if(composite && (skel == null || !skel.recognized || skel.bones.isEmpty()))
            throw new IllegalArgumentException("the selected skeleton resource has no decoded skel layer");
        // Keep non-deforming helper bones (notably *IK targets) in the skin too.
        // Otherwise Blender imports leaf helpers as Empties instead of armature bones.
        if(!joints.isEmpty() && skel != null && skel.recognized)
            for(SkelInfo.Bone bone : skel.bones)
                if(!joints.contains(bone.name))
                    joints.add(bone.name);
        Map<String, float[]> boneWorld = skeletonWorld(skel); // bone name -> native bind world matrix
        Map<String, double[]> boneBases = skel != null && skel.recognized
                ? BoneBasis.forSkeleton(skel) : Map.of();

        Buf bin = new Buf();
        List<Object> bufferViews = new ArrayList<>();
        List<Object> accessors = new ArrayList<>();

        // Per vertex-buffer: the attribute accessor indices shared by its submeshes.
        Map<Integer, Map<String, Object>> vbufAttribs = new LinkedHashMap<>();
        int vertices = 0;
        for(Map.Entry<Integer, Vbuf2Data> e : vbufs.entrySet()) {
            Vbuf2Data d = e.getValue();
            float[] pos = d.get("pos");
            if(pos == null)
                continue;
            Map<String, Object> attribs = new LinkedHashMap<>();
            attribs.put("POSITION", addVec3(bin, bufferViews, accessors, pos, d.num, true, true));
            float[] nrm = d.get("nrm");
            if(nrm != null)
                attribs.put("NORMAL", addVec3(bin, bufferViews, accessors, nrm, d.num, true, false));
            float[] tex = d.get("tex");
            if(tex != null)
                attribs.put("TEXCOORD_0", addVec2(bin, bufferViews, accessors, tex, d.num));
            float[] otex = d.get("otex");
            if(otex != null)
                attribs.put("TEXCOORD_1", addVec2(bin, bufferViews, accessors, otex, d.num));
            if(d.boneNames != null) {
                attribs.put("JOINTS_0", addJoints(bin, bufferViews, accessors, d, joints));
                attribs.put("WEIGHTS_0", addWeights(bin, bufferViews, accessors, d));
            }
            vbufAttribs.put(e.getKey(), attribs);
            vertices += d.num;
        }

        // manim layers -> glTF morph targets (per vbuf). A frame's positions are
        // deltas added to the base and interpolated linearly between frames, which
        // is exactly glTF morph-target semantics. (Samples have one vbuf; this is
        // handled for the single-vbuf case, the only one that occurs.)
        Map<Integer, List<Object>> vbufTargets = new LinkedHashMap<>();
        List<float[]> morphTimes = new ArrayList<>();   // per manim: keyframe times (+ loop close)
        List<int[]> morphSlots = new ArrayList<>();      // per manim: {baseSlot, frameCount}
        if(vbufs.size() == 1) {
            int vbufid = vbufs.keySet().iterator().next();
            Vbuf2Data d = vbufs.get(vbufid);
            List<MeshAnimInfo> manims = new ArrayList<>();
            for(Layer l : modelRes.layers)
                if(l.name.equals("manim")) {
                    MeshAnimInfo ma = MeshAnimInfo.parse(l.data);
                    if(ma.recognized)
                        manims.add(ma);
                }
            if(d != null && d.get("pos") != null && !manims.isEmpty()) {
                List<Object> targets = new ArrayList<>();
                for(MeshAnimInfo ma : manims) {
                    int base = targets.size();
                    for(MeshAnimInfo.Frame f : ma.frames) {
                        float[] delta = new float[d.num * 3];
                        if(f.pos != null && f.idx != null)
                            for(int k = 0; k < f.idx.length; k++) {
                                int v = f.idx[k];
                                if(v < 0 || v >= d.num)
                                    continue;
                                delta[v * 3] = f.pos[k * 3];          // Haven Z-up -> glTF Y-up
                                delta[v * 3 + 1] = f.pos[k * 3 + 2];  // (the same linear convert
                                delta[v * 3 + 2] = -f.pos[k * 3 + 1]; //  applied to positions)
                            }
                        targets.add(obj("POSITION", addVec3(bin, bufferViews, accessors, delta, d.num, false, true)));
                    }
                    float[] times = new float[ma.frames.size() + 1];
                    for(int fi = 0; fi < ma.frames.size(); fi++)
                        times[fi] = ma.frames.get(fi).time;
                    times[ma.frames.size()] = ma.len;     // loop close back to frame 0
                    morphTimes.add(times);
                    morphSlots.add(new int[]{base, ma.frames.size()});
                }
                if(!targets.isEmpty())
                    vbufTargets.put(vbufid, targets);
            }
        }

        List<Object> primitives = new ArrayList<>();
        int triangles = 0, submeshes = 0;
        for(int meshIndex = 0; meshIndex < meshes.size(); meshIndex++) {
            MeshInfo m = meshes.get(meshIndex);
            Map<String, Object> attribs = vbufAttribs.get(m.vbufid);
            if(attribs == null)
                continue;
            submeshes++;
            int idxAccessor = addIndices(bin, bufferViews, accessors, m.indices);
            Map<String, Object> prim = new LinkedHashMap<>();
            prim.put("attributes", new LinkedHashMap<>(attribs));
            prim.put("indices", idxAccessor);
            prim.put("material", meshMaterials.get(meshIndex));
            List<Object> targets = vbufTargets.get(m.vbufid);
            if(targets != null && !targets.isEmpty())
                prim.put("targets", targets);
            primitives.add(prim);
            triangles += m.indices.length / 3;
        }
        int morphCount = 0;
        for(List<Object> t : vbufTargets.values())
            morphCount = Math.max(morphCount, t.size());

        if(primitives.isEmpty()) {
            Map<String, Object> root = new LinkedHashMap<>();
            root.put("asset", obj("version", "2.0", "generator", "ResForge"));
            root.put("scene", 0);
            root.put("scenes", List.of(new LinkedHashMap<>()));
            byte[] glb = assembleGlb(Json.write(root), new byte[0]);
            return new Result(glb, vertices, triangles, submeshes, 0);
        }

        String base = baseName(sourceName);
        List<Object> nodes = new ArrayList<>();
        List<Object> sceneNodes = new ArrayList<>();

        // node 0 = the (optionally skinned) mesh
        Map<String, Object> meshNode = new LinkedHashMap<>();
        meshNode.put("mesh", 0);
        meshNode.put("name", base);
        nodes.add(meshNode);
        sceneNodes.add(0);

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("asset", obj("version", "2.0", "generator", "ResForge"));
        root.put("scene", 0);

        Map<String, Integer> boneNode = new LinkedHashMap<>();   // bone name -> glTF node index
        if(!joints.isEmpty()) {
            // Bone coordinates are reframed so Blender's local +Y points toward
            // child joints; leaves continue their incoming chain direction.
            float[] R = M4.fromQuat(SQRT_HALF, -SQRT_HALF, 0, 0);
            List<Object> skeletonRootChildren = null;
            Integer skeletonRootNode = null;

            if(skel != null && skel.recognized) {
                for(SkelInfo.Bone b : skel.bones) {
                    double[] basis = boneBases.get(b.name);
                    double[] parentBasis = boneBases.getOrDefault(b.parent,
                            new double[]{0, 0, 0, 1});
                    float[] q = rebaseBoneRotation(
                            M4.quat(b.ax, b.ay, b.az, b.ang), basis, parentBasis);
                    double[] p = BoneBasis.rotate(BoneBasis.conjugate(parentBasis),
                            new double[]{b.px, b.py, b.pz});
                    if(isSkeletonRoot(b, boneBases)) {
                        q = normalizeQuat(M4.qmul(axisRotation(), q));
                        p = axisConvert(p);
                    }
                    Map<String, Object> jn = new LinkedHashMap<>();
                    jn.put("name", b.name);
                    jn.put("translation", List.of(p[0], p[1], p[2]));
                    jn.put("rotation", List.of((double) q[1], (double) q[2], (double) q[3], (double) q[0]));
                    jn.put("extras", obj("resforgeBoneBasis",
                            List.of(basis[0], basis[1], basis[2], basis[3])));
                    boneNode.put(b.name, nodes.size());
                    nodes.add(jn);
                }
                List<Object> rootBones = new ArrayList<>();
                Map<Integer, List<Object>> childrenOf = new LinkedHashMap<>();
                for(SkelInfo.Bone b : skel.bones) {
                    int ni = boneNode.get(b.name);
                    if(b.parent.isEmpty() || !boneNode.containsKey(b.parent))
                        rootBones.add(ni);
                    else
                        childrenOf.computeIfAbsent(boneNode.get(b.parent), k -> new ArrayList<>()).add(ni);
                }
                for(Map.Entry<Integer, List<Object>> e : childrenOf.entrySet())
                    ((Map<String, Object>) nodes.get(e.getKey())).put("children", e.getValue());

                Map<String, Object> rootNode = new LinkedHashMap<>();
                rootNode.put("name", "ROOT");
                rootNode.put("children", rootBones);
                skeletonRootChildren = rootBones;
                skeletonRootNode = nodes.size();
                sceneNodes.add(skeletonRootNode);
                nodes.add(rootNode);

                Map<String, Object> marker = new LinkedHashMap<>();
                marker.put("name", SKELETON_BASIS_MARKER);
                marker.put("scale", List.of(0.0, 0.0, 0.0));
                sceneNodes.add(nodes.size());
                nodes.add(marker);
                root.put("extras", obj("resforgeSkeletonBasis", SKELETON_BASIS));
            }

            // skin.joints starts in unified influence order and includes unweighted
            // skeleton helpers. External bones get an identity node inside the same
            // ROOT hierarchy so Blender keeps one armature.
            List<Object> jointIndices = new ArrayList<>();
            float[] ibm = new float[joints.size() * 16];
            for(int j = 0; j < joints.size(); j++) {
                String name = joints.get(j);
                Integer ni = boneNode.get(name);
                float[] inv;
                if(ni != null && boneWorld.containsKey(name)) {
                    double[] basis = boneBases.get(name);
                    float[] basisMatrix = M4.fromQuat((float) basis[3], (float) basis[0],
                            (float) basis[1], (float) basis[2]);
                    inv = M4.rigidInverse(M4.mul(M4.mul(R, boneWorld.get(name)), basisMatrix));
                    jointIndices.add(ni);
                } else {
                    Map<String, Object> fn = new LinkedHashMap<>();
                    fn.put("name", name);
                    int fi = nodes.size();
                    nodes.add(fn);
                    if(skeletonRootChildren != null)
                        skeletonRootChildren.add(fi);
                    else
                        sceneNodes.add(fi);
                    jointIndices.add(fi);
                    inv = M4.identity();
                }
                System.arraycopy(inv, 0, ibm, j * 16, 16);
            }
            int ibmAccessor = addMat4(bin, bufferViews, accessors, ibm, joints.size());
            meshNode.put("skin", 0);
            Map<String, Object> skin = obj(
                    "inverseBindMatrices", ibmAccessor,
                    "joints", jointIndices);
            if(skeletonRootNode != null)
                skin.put("skeleton", skeletonRootNode);
            root.put("skins", List.of(skin));
        }

        // skan layers -> glTF animations (only for bones in the local skeleton).
        List<Object> animations = buildAnimations(animationRes, skel, boneNode,
                boneBases, bin, bufferViews, accessors);
        if(composite && animations.isEmpty())
            throw new IllegalArgumentException("the animation resource has no usable skan tracks");
        // manim morph weight animations (one per manim) targeting the mesh node's weights.
        for(int mi = 0; mi < morphSlots.size(); mi++) {
            int slotBase = morphSlots.get(mi)[0], cnt = morphSlots.get(mi)[1];
            float[] times = morphTimes.get(mi);
            float[] out = new float[times.length * morphCount];
            for(int ki = 0; ki < times.length; ki++) {
                int active = (ki < cnt) ? slotBase + ki : slotBase;   // last keyframe loops back to frame 0
                out[ki * morphCount + active] = 1f;
            }
            int inAcc = addScalar(bin, bufferViews, accessors, times);
            int outAcc = addScalarN(bin, bufferViews, accessors, out);
            Map<String, Object> sampler = obj("input", inAcc, "output", outAcc, "interpolation", "LINEAR");
            Map<String, Object> channel = obj("sampler", 0,
                    "target", obj("node", 0, "path", "weights"));
            animations.add(obj("name", "morph_" + mi, "samplers", List.of(sampler),
                    "channels", List.of(channel)));
        }
        if(!animations.isEmpty())
            root.put("animations", animations);

        root.put("scenes", List.of(obj("nodes", sceneNodes)));
        root.put("nodes", nodes);
        Map<String, Object> meshObj = obj("name", base, "primitives", primitives);
        if(morphCount > 0) {
            List<Object> weights = new ArrayList<>();
            for(int k = 0; k < morphCount; k++)
                weights.add(0.0);
            meshObj.put("weights", weights);
        }
        root.put("meshes", List.of(meshObj));

        if(!texMats.isEmpty()) {
            List<Object> images = new ArrayList<>();
            List<Object> textures = new ArrayList<>();
            for(int i = 0; i < texMats.size(); i++) {
                TexMat tm = texMats.get(i);
                int bv = addImage(bin, bufferViews, tm.image);
                images.add(obj("bufferView", bv, "mimeType", tm.mime));
                textures.add(obj("source", i, "sampler", 0));
            }
            root.put("textures", textures);
            root.put("images", images);
            root.put("samplers", List.of(obj("wrapS", 10497, "wrapT", 10497)));
        }
        List<Object> materials = new ArrayList<>();
        for(MeshMaterial gm : gltfMaterials) {
            Map<String, Object> pbr = new LinkedHashMap<>();
            Integer texOrd = matToTex.get(gm.matid);
            if(texOrd != null && texOrd >= 0 && texOrd < texMats.size())
                pbr.put("baseColorTexture", obj("index", texOrd, "texCoord", 0));
            pbr.put("metallicFactor", 0.0);
            pbr.put("roughnessFactor", 1.0);
            Map<String, Object> mat = new LinkedHashMap<>();
            mat.put("name", gm.name);
            mat.put("doubleSided", Boolean.TRUE);
            mat.put("alphaMode", "MASK");
            mat.put("alphaCutoff", 0.5);
            mat.put("pbrMetallicRoughness", pbr);
            materials.add(mat);
        }
        root.put("materials", materials);

        root.put("accessors", accessors);
        root.put("bufferViews", bufferViews);
        root.put("buffers", List.of(obj("byteLength", bin.size())));

        byte[] glb = assembleGlb(Json.write(root), bin.toByteArray());
        return new Result(glb, vertices, triangles, submeshes, texMats.size());
    }

public static RebuildResult rebuild(byte[] origRes, byte[] glb) {
        Glb g = parseGlb(glb);
        ResContainer res = ResContainer.parse(origRes);

        int vbufIdx = -1, vbufN = 0;
        List<Integer> meshIdxs = new ArrayList<>();
        for(int i = 0; i < res.layers.size(); i++) {
            String nm = res.layers.get(i).name;
            if(nm.equals("vbuf2")) { vbufN++; vbufIdx = i; }
            else if(nm.equals("mesh")) meshIdxs.add(i);
        }
        if(vbufN != 1 || meshIdxs.isEmpty())
            throw new IllegalArgumentException(
                    "rebuild needs one shared vbuf2 and at least one mesh; this resource has "
                            + vbufN + " vbuf2 and " + meshIdxs.size() + " mesh layers.");
        // morph layers re-encode at the new vertex count (shapes from the glTF targets,
        // timing kept from the original); the frame count must be unchanged.
        List<MeshAnimInfo> manims = new ArrayList<>();
        List<Integer> manimIdxs = new ArrayList<>();
        int totalFrames = 0;
        for(int i = 0; i < res.layers.size(); i++)
            if(res.layers.get(i).name.equals("manim")) {
                MeshAnimInfo mai = MeshAnimInfo.parse(res.layers.get(i).data);
                if(!mai.recognized)
                    throw new IllegalArgumentException("couldn't decode a manim layer to rebuild it.");
                manims.add(mai);
                manimIdxs.add(i);
                totalFrames += mai.frames.size();
            }
        boolean hasManim = !manims.isEmpty();

        byte[] origVbuf = res.layers.get(vbufIdx).data;
        Vbuf2Codec codec = Vbuf2Codec.parse(origVbuf);
        for(Vbuf2Codec.Attr at : codec.attrs) {
            String base = at.name.endsWith("2") ? at.name.substring(0, at.name.length() - 1) : at.name;
            if(!base.equals("pos") && !base.equals("nrm") && !base.equals("tex") && !base.equals("otex")
                    && !base.equals("tan") && !base.equals("bit")
                    && !at.name.equals("bones2") && !at.name.equals("bones"))
                throw new IllegalArgumentException("rebuild doesn't support the '" + at.name + "' vertex attribute yet.");
        }
        boolean hasNrm = codec.attr("nrm") != null, hasTex = codec.attr("tex") != null;
        boolean hasOtex = codec.attr("otex") != null, hasBones = codec.attr("bones") != null;
        boolean hasTan = codec.attr("tan") != null || codec.attr("bit") != null;
        SkeletonEdit skeletonEdit = readSkeletonEdit(g, res);

        // Original mesh templates provide ids, vbuf ids, and modern tto metadata.
        List<MeshInfo> meshTemplates = new ArrayList<>();
        Map<Integer, MeshInfo> matidToMesh = new LinkedHashMap<>();
        int vbufId = 0;
        for(int mi : meshIdxs) {
            MeshInfo m = MeshInfo.parse(res.layers.get(mi).data);
            if(m.recognized) {
                meshTemplates.add(m);
                matidToMesh.putIfAbsent(m.matid, m);
                vbufId = m.vbufid;
            }
        }
        List<Object> materials = materialsOf(g.root);

        // Concatenate each distinct vertex block (Blender splits per material; our own
        // export shares one), de-duplicating by POSITION accessor so a shared buffer
        // isn't copied per primitive.
        List<float[]> cPos = new ArrayList<>(), cNrm = new ArrayList<>(), cTex = new ArrayList<>(),
                cOtex = new ArrayList<>(), cJoints = new ArrayList<>(), cWeights = new ArrayList<>();
        Map<Integer, Integer> posOffset = new HashMap<>();
        int total = 0;
        List<int[]> meshTris = new ArrayList<>();
        List<Integer> meshMatids = new ArrayList<>();
        List<MeshInfo> outputTemplates = new ArrayList<>();
        List<List<float[]>> tChunks = new ArrayList<>();     // morph target deltas, per target -> chunks
        int[] targetN = {-1};

        IdentityHashMap<Map<String, Object>, double[]> primMatrix = primitiveMatrices(g.root);
        List<Map<String, Object>> primitives = allPrimitives(g.root);
        for(Map<String, Object> prim : primitives) {
            Map<String, Object> a = attributesOf(prim);
            if(a == null || !a.containsKey("POSITION"))
                continue;
            int posAcc = idx(a.get("POSITION"));
            int offset;
            if(posOffset.containsKey(posAcc)) {
                offset = posOffset.get(posAcc);
            } else {
                float[] p = readAccessor(g, posAcc, 3);
                double[] m = primMatrix.get(prim);
                if(m != null)
                    applyMatrix(p, m);
                int cnt = p.length / 3;
                cPos.add(axisInvert(p));
                if(hasNrm) {
                    float[] nrm = readVec(g, a, "NORMAL", 3, "normals");
                    if(m != null)
                        applyNormalMatrix(nrm, m);
                    cNrm.add(axisInvert(nrm));
                }
                if(hasTex) cTex.add(readVec(g, a, "TEXCOORD_0", 2, "UVs"));
                if(hasOtex) cOtex.add(readVec(g, a, "TEXCOORD_1", 2, "a second UV set"));
                if(hasBones) {
                    cJoints.add(readVec(g, a, "JOINTS_0", 4, "skinning joints"));
                    cWeights.add(readVec(g, a, "WEIGHTS_0", 4, "skinning weights"));
                }
                if(hasManim)
                    readMorphChunks(g, prim, cnt, tChunks, targetN, m);
                offset = total;
                posOffset.put(posAcc, offset);
                total += cnt;
            }
            int[] tris = readIndices(g, prim);
            for(int i = 0; i < tris.length; i++)
                tris[i] += offset;
            MeshInfo template = recoverMeshTemplate(prim, materials, meshTemplates, matidToMesh);
            if(template == null && isLostModernIdentity(prim, materials, primitives, meshTemplates)) {
                int expected = 0;
                for(MeshInfo m : meshTemplates)
                    expected += m.indices.length;
                if(tris.length != expected)
                    throw new IllegalArgumentException("this glTF was exported by an older ResForge version "
                            + "that lost modern mesh metadata, and its topology changed; re-export it before editing.");
                int from = 0;
                for(MeshInfo m : meshTemplates) {
                    int to = from + m.indices.length;
                    meshTris.add(java.util.Arrays.copyOfRange(tris, from, to));
                    meshMatids.add(m.matid);
                    outputTemplates.add(m);
                    from = to;
                }
            } else {
                int matid = template != null ? template.matid : recoverMatid(prim, materials, matidToMesh);
                meshTris.add(tris);
                meshMatids.add(matid);
                outputTemplates.add(template);
            }
        }
        if(total == 0)
            throw new IllegalArgumentException("the glTF has no mesh positions to rebuild from.");
        if(total > 0xffff)
            throw new IllegalArgumentException("rebuilt mesh has " + total + " vertices, over the 65535 limit.");

        codec.num = total;
        float[] allPos = concat(cPos);
        float[] allNrm = hasNrm ? concat(cNrm) : null;
        float[] allTex = hasTex ? concat(cTex) : null;
        codec.setAttr("pos", allPos);
        if(hasNrm) codec.setAttr("nrm", allNrm);
        if(hasTex) codec.setAttr("tex", allTex);
        if(hasOtex) codec.setAttr("otex", concat(cOtex));
        if(hasBones)
            rebuildWeights(g, concat(cJoints), concat(cWeights), codec, origVbuf, total,
                    skeletonEdit == null ? null : skeletonEdit.bones);
        if(hasTan) {
            // Haven stores tan and bit identically (verified across all sampled
            // normal-mapped models), so recompute one tangent and write it to both.
            if(allNrm == null || allTex == null)
                throw new IllegalArgumentException("rebuilding tangents needs normals and UVs, which the glTF lacks.");
            float[] tangents = computeTangents(allPos, allNrm, allTex, total, meshTris);
            if(codec.attr("tan") != null) codec.setAttr("tan", tangents);
            if(codec.attr("bit") != null) codec.setAttr("bit", tangents);
        }
        byte[] newVbuf = codec.encode();

        // Re-encode each manim at the new vertex count (shapes from the glTF targets).
        Map<Integer, byte[]> manimReplace = new HashMap<>();
        if(hasManim) {
            if(targetN[0] != totalFrames)
                throw new IllegalArgumentException(
                        "the glTF has " + targetN[0] + " shape keys but the model's morph animation has "
                                + totalFrames + " frames; rebuild can't add or remove morph frames yet.");
            float[][] combined = new float[totalFrames][];
            for(int t = 0; t < totalFrames; t++)
                combined[t] = concat(tChunks.get(t));
            int gi = 0;
            for(int m = 0; m < manims.size(); m++) {
                MeshAnimInfo mai = manims.get(m);
                int cntF = mai.frames.size();
                float[][] fd = new float[cntF][];
                for(int f = 0; f < cntF; f++)
                    fd[f] = combined[gi + f];
                manimReplace.put(manimIdxs.get(m), mai.encodeWith(fd, total, 1e-6f));
                gi += cntF;
            }
        }

        // Rebuild the layer list: vbuf2 in place, all old mesh layers replaced by the
        // new submeshes at the first mesh position, manim layers re-encoded, others kept.
        List<Layer> outLayers = new ArrayList<>();
        java.util.Set<Integer> meshSet = new java.util.HashSet<>(meshIdxs);
        boolean meshEmitted = false;
        int totalTris = 0;
        for(int i = 0; i < res.layers.size(); i++) {
            if(i == vbufIdx) {
                outLayers.add(new Layer("vbuf2", newVbuf));
            } else if(meshSet.contains(i)) {
                if(!meshEmitted) {
                    for(int s = 0; s < meshTris.size(); s++) {
                        int matid = meshMatids.get(s);
                        MeshInfo tmpl = outputTemplates.get(s);
                        outLayers.add(new Layer("mesh", encodeMeshRaw(matid, tmpl, vbufId, meshTris.get(s))));
                        totalTris += meshTris.get(s).length / 3;
                    }
                    meshEmitted = true;
                }
            } else if(manimReplace.containsKey(i)) {
                outLayers.add(new Layer("manim", manimReplace.get(i)));
            } else if(skeletonEdit != null && skeletonEdit.changed
                    && i == skeletonEdit.layerIndex) {
                outLayers.add(new Layer("skel", SkelInfo.encodeVer1(skeletonEdit.bones)));
            } else {
                outLayers.add(res.layers.get(i));
            }
        }
        res.layers.clear();
        res.layers.addAll(outLayers);
        return new RebuildResult(res.serialize(), total, totalTris, hasBones,
                skeletonEdit != null && skeletonEdit.changed);
    }

public void writePtyAnswer(String answer) {
        try {
            if (answer == null) {
                LOG.fine("[PTY write] \\x1b (Cancel/ESC)");
                sendCancelToPty(new byte[]{0x1b});
            } else if (answer.startsWith("MULTI:")) {
                Set<String> wanted = new HashSet<>();
                for (String d : answer.substring(6).split(",")) wanted.add(d.strip());
                // Re-read current screen to get actual checkbox states before sending toggles.
                // Sending a digit toggles the checkbox, so we must only send digits for
                // options whose current state differs from the desired state.
                List<String> lines = screenLines.get();
                Optional<ChoiceMenuModel> currentMenu = screenContentDetector.detectChoiceMenu(lines);
                List<ChoiceMenuModel.Option> currentOptions = currentMenu
                        .map(ChoiceMenuModel::options)
                        .orElseGet(() -> {
                            ChoiceMenuModel m = model.getActiveChoiceMenu();
                            return m != null ? m.options() : List.of();
                        });
                List<String> toggles = computeCheckboxToggles(wanted, currentOptions);
                LOG.fine("[PTY write] MULTI wanted=" + wanted + " toggles=" + toggles);
                Thread t = new Thread(() -> {
                    try {
                        for (String digit : toggles) {
                            connector.write(digit.strip());
                            Thread.sleep(100);
                        }
                        // Right arrow to submit the selection
                        connector.write(new byte[]{0x1b, '[', 'C'});
                    } catch (IOException ex) {
                        LOG.warning("writePtyAnswer MULTI write failed: " + ex.getMessage());
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }, "pty-multiselect");
                t.setDaemon(true);
                t.start();
                clearActiveChoiceMenu();
            } else if (answer.startsWith("MULTI_TYPE:")) {
                // Format: MULTI_TYPE:checks:typeN:text
                // e.g. MULTI_TYPE:1,3:5:my text  or  MULTI_TYPE::5:my text
                int sep1 = answer.indexOf(':', 11);
                int sep2 = answer.indexOf(':', sep1 + 1);
                String checksStr = answer.substring(11, sep1);
                int typeN = Integer.parseInt(answer.substring(sep1 + 1, sep2));
                String typeText = answer.substring(sep2 + 1);
                Set<String> wanted = checksStr.isBlank() ? Set.of()
                        : new HashSet<>(List.of(checksStr.split(",")));
                LOG.fine("[PTY write] MULTI_TYPE wanted=" + wanted + " typeN=" + typeN + " text=" + typeText);
                Thread t = new Thread(() -> {
                    try {
                        // 1. Toggle non-type checkboxes
                        List<String> lines = screenLines.get();
                        Optional<ChoiceMenuModel> currentMenu = screenContentDetector.detectChoiceMenu(lines);
                        List<ChoiceMenuModel.Option> currentOptions = currentMenu
                                .map(ChoiceMenuModel::options)
                                .orElseGet(() -> {
                                    ChoiceMenuModel m = model.getActiveChoiceMenu();
                                    return m != null ? m.options() : List.of();
                                });
                        for (String digit : computeCheckboxToggles(wanted, currentOptions)) {
                            connector.write(digit.strip());
                            Thread.sleep(100);
                        }
                        // 2. Re-read screen to find current ❯ position
                        Thread.sleep(200);
                        int currentN = findCurrentOptionNum(screenLines.get());
                        // 3. Navigate to type-input option
                        int delta = typeN - currentN;
                        byte[] arrow = delta < 0
                                ? new byte[]{0x1b, '[', 'A'}
                                : new byte[]{0x1b, '[', 'B'};
                        for (int i = 0; i < Math.abs(delta); i++) {
                            connector.write(arrow);
                            Thread.sleep(80);
                        }
                        // 4. Type text
                        Thread.sleep(100);
                        connector.write(typeText);
                        // 5. Move cursor off type-input field (up arrow)
                        Thread.sleep(100);
                        connector.write(new byte[]{0x1b, '[', 'A'});
                        // 6. Submit with right arrow
                        Thread.sleep(100);
                        connector.write(new byte[]{0x1b, '[', 'C'});
                    } catch (IOException ex) {
                        LOG.warning("writePtyAnswer MULTI_TYPE write failed: " + ex.getMessage());
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }, "pty-multitype");
                t.setDaemon(true);
                t.start();
                clearActiveChoiceMenu();
            } else if (answer.startsWith("TYPE:")) {
                int sep = answer.indexOf(':', 5);
                String digit = answer.substring(5, sep);
                String text = answer.substring(sep + 1);
                ChoiceMenuModel current = detectCurrentMenu();
                int targetIdx = Integer.parseInt(digit) - 1;
                // currentIdx = actual PTY cursor position (re-read from screen); currentHasTextInput
                // = cursor is on a text-input option (digits go to its text field, not to navigation).
                final int currentIdx = current != null ? current.defaultOptionIndex() : targetIdx;
                boolean currentHasTextInput = current != null
                        && isTextInputOption(current.options().get(currentIdx));
                LOG.fine("[PTY write] type-input digit=" + digit + " text=" + text
                        + " currentHasTextInput=" + currentHasTextInput);
                Thread t = new Thread(() -> {
                    try {
                        if (currentHasTextInput) {
                            int delta = targetIdx - currentIdx;
                            if (delta != 0) {
                                byte[] arrow = delta < 0 ? new byte[]{0x1b, '[', 'A'} : new byte[]{0x1b, '[', 'B'};
                                for (int i = 0; i < Math.abs(delta); i++) {
                                    connector.write(arrow);
                                    Thread.sleep(80);
                                }
                                Thread.sleep(100);
                            }
                            connector.write(text);
                            Thread.sleep(200);
                            connector.write("\r");
                        } else {
                            connector.write(digit);
                            Thread.sleep(200);
                            connector.write(text);
                            Thread.sleep(200);
                            connector.write("\r");
                        }
                    } catch (IOException ex) {
                        LOG.warning("writePtyAnswer TYPE write failed: " + ex.getMessage());
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }, "pty-typeinput");
                t.setDaemon(true);
                t.start();
                clearActiveChoiceMenu();
            } else if (answer.startsWith("ARROW:")) {
                int targetIdx = Integer.parseInt(answer.substring(6));
                ChoiceMenuModel current = model.getActiveChoiceMenu();
                int currentIdx = current != null ? current.defaultOptionIndex() : 0;
                int delta = targetIdx - currentIdx;
                LOG.fine("[PTY write] ARROW targetIdx=" + targetIdx + " currentIdx=" + currentIdx + " delta=" + delta);
                clearActiveChoiceMenu();
                if (delta == 0) {
                    connector.write("\r");
                } else {
                    byte[] arrow = delta < 0 ? new byte[]{0x1b, '[', 'A'} : new byte[]{0x1b, '[', 'B'};
                    Thread t = new Thread(() -> {
                        try {
                            for (int idx = 0; idx < Math.abs(delta); idx++) {
                                connector.write(arrow);
                                Thread.sleep(80);
                            }
                            connector.write("\r");
                        } catch (IOException ex) {
                            LOG.warning("writePtyAnswer ARROW write failed: " + ex.getMessage());
                        } catch (InterruptedException ie) {
                            Thread.currentThread().interrupt();
                        }
                    }, "pty-arrow-select");
                    t.setDaemon(true);
                    t.start();
                }
            } else {
                ChoiceMenuModel current = detectCurrentMenu();
                // currentHasTextInput = PTY cursor (❯) is on a text-input option (re-read from
                // screen); digits go into its text field, so use arrow-key navigation instead.
                int currentIdx2 = current != null ? current.defaultOptionIndex() : 0;
                boolean currentHasTextInput = current != null
                        && isTextInputOption(current.options().get(currentIdx2));
                LOG.fine("[PTY write] else-branch answer=" + answer + " currentIdx=" + currentIdx2 + " currentHasTextInput=" + currentHasTextInput);
                if (currentHasTextInput && answer.matches("[0-9]")) {
                    int targetIdx = answer.charAt(0) - '1';
                    int currentIdx = currentIdx2;
                    int delta = targetIdx - currentIdx;
                    LOG.fine("[PTY write] ARROW-digit targetIdx=" + targetIdx + " currentIdx=" + currentIdx + " delta=" + delta);
                    clearActiveChoiceMenu();
                    if (delta == 0) {
                        connector.write("\r");
                    } else {
                        byte[] arrow = delta < 0 ? new byte[]{0x1b, '[', 'A'} : new byte[]{0x1b, '[', 'B'};
                        Thread t = new Thread(() -> {
                            try {
                                for (int i = 0; i < Math.abs(delta); i++) {
                                    connector.write(arrow);
                                    Thread.sleep(80);
                                }
                                connector.write("\r");
                            } catch (IOException ex) {
                                LOG.warning("writePtyAnswer ARROW-digit write failed: " + ex.getMessage());
                            } catch (InterruptedException ie) {
                                Thread.currentThread().interrupt();
                            }
                        }, "pty-arrow-digit");
                        t.setDaemon(true);
                        t.start();
                    }
                } else if (answer.matches("[0-9]{2,}") && menuCursorNumber(current) > 0) {
                    // Items 10+ cannot be typed (a digit selects immediately): move the PTY
                    // cursor onto the item with arrow keys, then Enter.
                    int delta = Integer.parseInt(answer) - menuCursorNumber(current);
                    LOG.fine("[PTY write] ARROW-number answer=" + answer + " delta=" + delta);
                    clearActiveChoiceMenu();
                    sendArrowsThenEnter(delta, "pty-arrow-number");
                } else {
                    boolean isMenuDigit = answer.matches("[0-9]");
                    String toWrite = isMenuDigit ? answer : answer + "\r";
                    LOG.fine("[PTY write] " + toWrite.replace("\r", "\\r").replace("\n", "\\n"));
                    connector.write(toWrite);
                    clearActiveChoiceMenu();
                }
            }
        } catch (IOException ex) {
            LOG.warning("writePtyAnswer failed: " + ex.getMessage());
        }
    }

