public PtyProcess start(String workingDir, ClaudeProfile profile, String extraCliArgs,
                            SessionMode mode, String resumeSessionId) throws IOException {
        if (workingDir == null || workingDir.isBlank()) {
            throw new IllegalArgumentException("workingDir must not be blank");
        }

        // stop() cleans up the previous session's settings.local.json (if any)
        stop();
        this.workingDir = workingDir;

        String executable = ClaudeCodePreferences.resolveClaudeExecutable();

        Map<String, String> env = buildEnv(profile, ClaudeCodePreferences.getProfilesDir());

        // OpenAI proxy: register session and inject ANTHROPIC_BASE_URL pointing to internal proxy
        if (profile != null
                && profile.getConnectionType() == ClaudeProfile.ConnectionType.OPENAI_PROXY) {
            ClaudeCodeStatusService mcpSvc = Lookup.getDefault().lookup(ClaudeCodeStatusService.class);
            if (mcpSvc != null && mcpSvc.isServerRunning()) {
                String uuid = UUID.randomUUID().toString();
                io.github.nbplugins.claudecodegui.settings.ProxyConfiguration proxyConfig =
                        io.github.nbplugins.claudecodegui.settings.ProxyConfiguration.from(profile);
                if (mcpSvc instanceof io.github.nbplugins.claudecodegui.ClaudeCodeInstaller installer) {
                    // Prefer the profile-id-aware overload so the proxy can look up
                    // per-model experimental prompt-caching settings.
                    installer.registerOpenAIProxy(uuid, profile.getBaseUrl(), profile.getApiKey(),
                            proxyConfig, profile.getId());
                } else {
                    mcpSvc.registerOpenAIProxy(uuid, profile.getBaseUrl(), profile.getApiKey(), proxyConfig);
                }
                openAIProxyUuid = uuid;
                env.put("ANTHROPIC_BASE_URL",
                        "http://127.0.0.1:" + mcpSvc.getServerPort() + "/openai-proxy/" + uuid);
                env.put("ANTHROPIC_AUTH_TOKEN", "sk-proxy-internal");
                disableAutoModeServerCheck(env);
                LOG.info("OpenAI proxy registered: uuid=" + uuid
                        + ", profile=" + profile.getName()
                        + ", target=" + profile.getBaseUrl());
            } else {
                LOG.warning("OpenAI proxy: MCP server not running — proxy cannot be started");
            }
        }

        // ChatGPT subscription: pre-emptively refresh the OAuth token, register the
        // session, and inject ANTHROPIC_BASE_URL pointing to the internal Codex proxy.
        if (profile != null
                && profile.getConnectionType() == ClaudeProfile.ConnectionType.OPENAI_SUBSCRIPTION) {
            ClaudeCodeStatusService mcpSvc = Lookup.getDefault().lookup(ClaudeCodeStatusService.class);
            if (mcpSvc != null && mcpSvc.isServerRunning()) {
                try {
                    String accessToken = new io.github.nbplugins.claudecodegui.chatgptauth.ChatGptTokenManager()
                            .getValidAccessToken(profile);
                    String uuid = UUID.randomUUID().toString();
                    mcpSvc.registerChatgptSubscriptionProxy(uuid, profile.getId(), accessToken,
                            profile.getChatgptAccountId(),
                            io.github.nbplugins.claudecodegui.settings.ProxyConfiguration.from(profile));
                    openAIProxyUuid = uuid;
                    env.put("ANTHROPIC_BASE_URL",
                            "http://127.0.0.1:" + mcpSvc.getServerPort() + "/openai-proxy/" + uuid);
                    env.put("ANTHROPIC_AUTH_TOKEN", "sk-proxy-internal");
                    disableAutoModeServerCheck(env);
                    LOG.info("ChatGPT subscription proxy registered: uuid=" + uuid
                            + ", profile=" + profile.getName());
                } catch (io.github.nbplugins.claudecodegui.chatgptauth.OAuthException e) {
                    LOG.warning("ChatGPT subscription auth failed at session start: " + e.getMessage());
                    throw new IOException("ChatGPT sign-in expired — please re-authenticate in Profile settings: "
                            + e.getMessage(), e);
                }
            } else {
                LOG.warning("ChatGPT subscription proxy: MCP server not running — proxy cannot be started");
            }
        }

        boolean apiKeyHelper = profile != null && !profile.getApiKey().isBlank() && profile.getBaseUrl().isBlank()
                && profile.getConnectionType() != ClaudeProfile.ConnectionType.OPENAI_PROXY
                && profile.getConnectionType() != ClaudeProfile.ConnectionType.OPENAI_SUBSCRIPTION;
        LOG.info("Starting Claude: profile=" + (profile != null ? profile.getName() + " (" + profile.getConnectionType() + ")" : "Default")
                + ", apiKeyHelper=" + (apiKeyHelper ? "SET" : "NOT SET")
                + ", ANTHROPIC_AUTH_TOKEN=" + (!env.getOrDefault("ANTHROPIC_AUTH_TOKEN", "").isBlank() ? "SET" : "NOT SET")
                + ", ANTHROPIC_BASE_URL=" + env.getOrDefault("ANTHROPIC_BASE_URL", "(not set)")
                + ", CLAUDE_CONFIG_DIR=" + env.getOrDefault("CLAUDE_CONFIG_DIR", "(inherited)")
                + ", HTTP_PROXY="  + env.getOrDefault("HTTP_PROXY",  env.getOrDefault("http_proxy",  "(not set)"))
                + ", HTTPS_PROXY=" + env.getOrDefault("HTTPS_PROXY", env.getOrDefault("https_proxy", "(not set)"))
                + ", NO_PROXY="    + env.getOrDefault("NO_PROXY",    env.getOrDefault("no_proxy",    "(not set)"))
                + ", sessionMode=" + mode
                + (mode == SessionMode.RESUME_SPECIFIC ? ", resumeId=" + resumeSessionId : ""));

        List<String> cmd = new ArrayList<>();
        cmd.add(executable);
        ClaudeCodeStatusService mcp = Lookup.getDefault().lookup(ClaudeCodeStatusService.class);
        LOG.fine("MCP service lookup: " + (mcp == null ? "null" : mcp.getClass().getName())
                + ", running=" + (mcp != null && mcp.isServerRunning())
                + ", port=" + (mcp != null ? mcp.getServerPort() : -1));
        if (mcp != null && mcp.isServerRunning()) {
            int port = mcp.getServerPort();
            if (io.github.nbplugins.claudecodegui.settings.ClaudeCodePreferences.isMcpEnabled()) {
                // Pass MCP server config via --mcp-config (Claude 2.x no longer reads
                // mcpServers from settings.local.json; --mcp-config works in TUI mode).
                // On Windows, inline JSON gets quote-stripped by CreateProcess, so we
                // write to a temp file and pass the file path instead.
                cmd.add("--mcp-config");
                try {
                    Path tmpCfg = writeMcpConfigTempFile(port);
                    mcpConfigTempFile = tmpCfg;
                    cmd.add(tmpCfg.toAbsolutePath().toString());
                    LOG.info("Passing --mcp-config via temp file: " + tmpCfg);
                } catch (IOException e) {
                    LOG.warning("Could not write --mcp-config temp file, falling back to inline JSON: " + e.getMessage());
                    cmd.add(buildMcpConfigJson(port));
                    LOG.info("Passing --mcp-config with netbeans SSE server on port " + port);
                }
            } else {
                LOG.info("MCP integration disabled by user preference; skipping --mcp-config");
            }
            try {
                writeSettingsLocalJson(workingDir, port, profile);
            } catch (IOException e) {
                LOG.warning("Could not write .claude/settings.local.json: " + e.getMessage());
            }
        }

        appendSessionFlags(cmd, workingDir, env, extraCliArgs, mode, resumeSessionId);

        lastCommand = toShellCommand(cmd);
        LOG.info("Claude command: " + lastCommand + " (dir: " + workingDir + ")");
        PtyProcessBuilder builder = new PtyProcessBuilder(cmd.toArray(new String[0]))
                .setEnvironment(env)
                .setDirectory(workingDir)
                .setInitialColumns(120)
                .setInitialRows(40)
                .setConsole(false)
                .setRedirectErrorStream(true);

        PtyProcess p;
        try {
            p = builder.start();
        } catch (IOException ptyEx) {
            // pty4j's exec_pty() often yields "Exec_tty error:Unknown reason" even for
            // mundane failures (binary not found, no execute permission). Run the same
            // command via plain ProcessBuilder — purely to get a meaningful errno message
            // from the JVM — then rethrow that exception instead.
            try {
                new ProcessBuilder(cmd.toArray(new String[0]))
                        .directory(new java.io.File(workingDir))
                        .start()
                        .destroyForcibly();
            } catch (IOException betterEx) {
                throw betterEx;
            }
            throw ptyEx;
        }
        ptyProcess = p;
        LOG.fine("Claude PTY started, pid=" + p.pid());
        return p;
    }

public Optional<ChoiceMenuModel> detectChoiceMenu(List<String> screenLines) {
        if (screenLines == null || screenLines.isEmpty()) return Optional.empty();

        // Find the last option line (bottom-most) on screen
        int lastOptionRow = -1;
        for (int i = screenLines.size() - 1; i >= 0; i--) {
            if (OPTION_LINE.matcher(screenLines.get(i).trim()).matches()) {
                lastOptionRow = i;
                break;
            }
        }
        if (lastOptionRow < 0) return detectUnnumberedChoiceMenu(screenLines);
        LOG.fine(tag + "[ScreenContentDetector] lastOptionRow=" + lastOptionRow
                + " line=" + screenLines.get(lastOptionRow).trim());

        // Walk upward to collect all contiguous option lines.
        // Allow up to 3 consecutive "continuation" lines (non-option, non-blank)
        // to handle wrapped option text that overflows to the next screen line.
        // Stop as soon as we encounter option "1." — it is always the first item of the
        // menu, so anything above it belongs to a previous context.
        //
        // optionRows[i] stores the screen-line index of each option (parallel to options list).
        List<ChoiceMenuModel.Option> options = new ArrayList<>();
        List<Integer> optionRows = new ArrayList<>();
        int firstOptionRow = lastOptionRow;
        int continuationCount = 0;
        for (int i = lastOptionRow; i >= 0; i--) {
            String trimmed = screenLines.get(i).trim();
            if (OPTION_LINE.matcher(trimmed).matches()) {
                ChoiceMenuModel.Option opt = extractOption(trimmed, options.size() + 1);
                options.add(0, opt);
                optionRows.add(0, i);
                firstOptionRow = i;
                continuationCount = 0;
                // Option "1" is always the first — stop collecting here
                if ("1".equals(opt.response())) break;
            } else if (isSeparatorLine(trimmed)) {
                // structural separator between option groups — don't count toward continuationCount
            } else if (!trimmed.isBlank()) {
                continuationCount++;
                if (continuationCount > 8) {
                    LOG.fine(tag + "[ScreenContentDetector] stopped upward scan at row " + i
                            + " (continuationCount>8): " + trimmed);
                    break;
                }
            }
        }

        // Collect per-option description: the first candidate line immediately below each
        // option line that looks like an intentional description (not a wrapped continuation
        // of the option text, not a hint line, not a separator).
        // A description line must:
        //   - be non-blank and non-separator
        //   - not be another option line
        //   - not be a keyboard-hint line (contains "·" or starts with "Esc"/"Tab"/"Enter")
        //   - have a shorter leading-whitespace indent than a deeply-wrapped continuation
        //     (continuation wraps are typically indented to align with the option text start,
        //      so they have large indent; description lines have moderate indent ≤ 8 spaces)
        for (int oi = 0; oi < options.size(); oi++) {
            int optRow = optionRows.get(oi);
            int nextOptRow = (oi + 1 < optionRows.size()) ? optionRows.get(oi + 1) : lastOptionRow + 4;
            for (int j = optRow + 1; j < Math.min(nextOptRow, screenLines.size()); j++) {
                String raw = screenLines.get(j);
                String line = raw.trim();
                if (line.isBlank()) break;
                if (OPTION_LINE.matcher(line).matches()) break;
                if (HIDDEN_ITEMS_LINE.matcher(line).matches()) break;
                // Skip keyboard-hint lines; "shift+tab to approve" also marks the option
                // as requiring free-text input (hasTextInput=true).
                if (isHintLine(line)) {
                    if (line.toLowerCase().startsWith("shift+tab")) {
                        ChoiceMenuModel.Option prev = options.get(oi);
                        options.set(oi, new ChoiceMenuModel.Option(
                                prev.display(), prev.response(), prev.description(),
                                prev.checked(), prev.hasCheckbox(), true));
                    }
                    break;
                }
                // Skip separator lines
                if (isSeparatorLine(line)) break;
                // Description must be indented (at least 1 leading space) and not too deeply
                // indented (> 8 spaces = wrapped continuation of the option text itself).
                int indent = raw.length() - raw.stripLeading().length();
                if (indent == 0 || indent > 8) break;
                ChoiceMenuModel.Option prev = options.get(oi);
                options.set(oi, new ChoiceMenuModel.Option(
                        prev.display(), prev.response(), line, prev.checked(), prev.hasCheckbox()));
                break;
            }
        }

        if (options.isEmpty()) return Optional.empty();
        LOG.fine(tag + "[ScreenContentDetector] collected options=" + options
                + " firstOptionRow=" + firstOptionRow);

        // Bug 1 guard: a single option with no Esc/cancel/amend hint in the
        // 3 lines below lastOptionRow is likely an echoed previous selection,
        // not a real menu. Real menus always have ≥2 options OR show a hint.
        if (options.size() == 1) {
            boolean hasHint = false;
            for (int i = lastOptionRow + 1; i < Math.min(lastOptionRow + 4, screenLines.size()); i++) {
                String lower = screenLines.get(i).toLowerCase();
                if (lower.contains("esc") || lower.contains("cancel") || lower.contains("amend")) {
                    hasHint = true;
                    break;
                }
            }
            if (!hasHint) {
                LOG.fine(tag + "[ScreenContentDetector] rejected: single option with no hint");
                return Optional.empty();
            }
        }

        // First non-blank line above the first option is the question
        String question = "";
        for (int i = firstOptionRow - 1; i >= 0; i--) {
            String line = screenLines.get(i).trim();
            if (!line.isBlank()) {
                question = line;
                break;
            }
        }

        // Guard: Claude Code Ink menus always show a cursor glyph (❯ / ▶ / >) on the
        // currently-selected option. Numbered lists in Claude's own output never have
        // a cursor, so requiring one eliminates false positives entirely.
        boolean hasCursor = false;
        int cursorNumber = 0;
        for (int i = firstOptionRow; i <= lastOptionRow; i++) {
            if (CURSOR_LINE.matcher(screenLines.get(i).trim()).matches()) {
                hasCursor = true;
                cursorNumber = parseOptionNumber(screenLines.get(i).trim());
                break;
            }
        }
        if (!hasCursor) {
            LOG.fine(tag + "[ScreenContentDetector] rejected: no cursor glyph found");
            return Optional.empty();
        }

        // Guard: if a separator line exists below the last option, a real menu always has
        // at least one option line below that separator (e.g. "6. Chat about this" in
        // interview-style menus). An echoed user prompt has no options below the separator
        // that frames the input prompt ❯. Applies only when a separator is actually found.
        int firstSepBelow = -1;
        for (int i = lastOptionRow + 1; i < screenLines.size(); i++) {
            if (isSeparatorLine(screenLines.get(i).trim())) { firstSepBelow = i; break; }
        }
        if (firstSepBelow >= 0) {
            boolean hasOptionBelowSep = false;
            for (int i = firstSepBelow + 1; i < screenLines.size(); i++) {
                if (OPTION_LINE.matcher(screenLines.get(i).trim()).matches()) {
                    hasOptionBelowSep = true; break;
                }
            }
            if (!hasOptionBelowSep) {
                LOG.fine(tag + "[ScreenContentDetector] rejected: separator at row "
                        + firstSepBelow + " with no options below: "
                        + screenLines.get(firstSepBelow).trim());
                return Optional.empty();
            }
        }

        LOG.fine(tag + "[ScreenContentDetector] detected prompt: \"" + question + "\" options=" + options);
        // Scrolling menu: Claude marks hidden items with a leading ↑ / ↓ on the edge option
        // and/or a "… +N models" line below the list.
        boolean scrollable = screenLines.get(firstOptionRow).trim().startsWith("\u2191")
                || screenLines.get(lastOptionRow).trim().startsWith("\u2193");
        for (int i = lastOptionRow + 1; !scrollable && i < Math.min(lastOptionRow + 4, screenLines.size()); i++) {
            if (HIDDEN_ITEMS_LINE.matcher(screenLines.get(i).trim()).matches()) scrollable = true;
        }
        return Optional.of(new ChoiceMenuModel(question, options, 0, scrollable, cursorNumber));
    }

Optional<ChoiceMenuModel> detectUnnumberedChoiceMenu(List<String> screenLines) {
        if (screenLines == null || screenLines.isEmpty()) return Optional.empty();

        // Step 1: find footer — last non-blank line containing '·' and navigation/Esc keywords
        int footerRow = -1;
        for (int i = screenLines.size() - 1; i >= 0; i--) {
            String line = screenLines.get(i);
            if (line.isBlank()) continue;
            String trimmed = line.trim();
            if (isUnnumberedFooterLine(trimmed)) {
                footerRow = i;
                break;
            }
            // First non-blank line from bottom is not a footer → no unnumbered menu
            break;
        }
        if (footerRow < 0) return Optional.empty();

        // Step 2: walk upward from footer collecting option blocks (pairs: desc + main, bottom-up).
        // Stop when we hit a non-option line (search box, separator, 0-indent title, numbered option).
        // Also stop if we encounter a footer-like line mid-screen (handles mid-render footer redraws).
        List<String> blockMainLines = new ArrayList<>();
        List<String> blockDescLines = new ArrayList<>();
        int stopRow = -1; // row where we stopped (first non-option line above options)

        int i = footerRow - 1;
        boolean firstBlock = true;
        while (i >= 0) {
            if (screenLines.get(i).isBlank()) {
                if (!firstBlock) {
                    // A blank line after at least one option block was already collected marks
                    // the end of the option list (real menu items are never blank-separated from
                    // each other) — stop here instead of skipping through unrelated prose above.
                    stopRow = i;
                    break;
                }
                // Allow a single blank gap between the footer and the first (bottom-most) option.
                while (i >= 0 && screenLines.get(i).isBlank()) i--;
                if (i < 0) break;
            }

            String raw = screenLines.get(i);
            String trimmed = raw.trim();

            // Stop conditions — record stop row for header search
            if (isSeparatorLine(trimmed) || OPTION_LINE.matcher(trimmed).matches()) {
                break; // separator or numbered option → not an unnumbered menu above
            }
            if (isBoxDrawingLine(trimmed) || trimmed.contains("\u2315")) { // ⌕
                // Search box / box border → stop options, continue upward for header
                stopRow = i;
                break;
            }
            if (isUnnumberedFooterLine(trimmed)) {
                // Footer appeared mid-screen (cursor-movement redraw) → treat as footer, stop
                break;
            }
            // Line with no leading indent and no ❯ → title / non-option line
            boolean startsWithCursor = !raw.isEmpty() && "\u276F\u25B6>".indexOf(raw.charAt(0)) >= 0;
            boolean hasIndent = !raw.isEmpty() && Character.isWhitespace(raw.charAt(0));
            if (!startsWithCursor && !hasIndent) {
                // This is the title line itself
                stopRow = i;
                break;
            }

            // Collect this block: desc = current line, main = line above (if non-blank).
            // Only pair the two lines when the lower one carries the metadata separator "·"
            // (e.g. "23 hours ago · bugfix/new-kafka · 1MB") — the shape real 2-line unnumbered
            // entries use. Without that marker, treat the line as its own single-line option so
            // two genuinely separate options (e.g. "No, exit" / "Yes, I trust this folder") don't
            // get fused into one.
            String desc = trimmed;
            String main = null;
            if (desc.indexOf('·') >= 0 && i - 1 >= 0 && !screenLines.get(i - 1).isBlank()) {
                String raw2 = screenLines.get(i - 1);
                String trimmed2 = raw2.trim();
                if (!isSeparatorLine(trimmed2) && !OPTION_LINE.matcher(trimmed2).matches()
                        && !isBoxDrawingLine(trimmed2) && !trimmed2.contains("\u2315")
                        && !isUnnumberedFooterLine(trimmed2)) {
                    main = trimmed2;
                    i--;
                }
            }
            i--;
            if (main == null) {
                // Single-line block — treat as main with no description
                main = desc;
                desc = null;
            }
            blockMainLines.add(0, main);
            blockDescLines.add(0, desc);
            firstBlock = false;
        }

        if (blockMainLines.size() < 2) return Optional.empty();

        // Step 3: build options, detect selected (❯)
        List<ChoiceMenuModel.Option> options = new ArrayList<>();
        int defaultIdx = 0;
        boolean foundCursor = false;
        for (int oi = 0; oi < blockMainLines.size(); oi++) {
            String main = blockMainLines.get(oi);
            String desc = blockDescLines.get(oi);
            if (!main.isEmpty() && "\u276F\u25B6>".indexOf(main.charAt(0)) >= 0) {
                main = main.substring(1).stripLeading();
                if (!foundCursor) {
                    defaultIdx = oi;
                    foundCursor = true;
                }
            }
            options.add(new ChoiceMenuModel.Option(main, "ARROW:" + oi, desc));
        }
        if (!foundCursor) {
            LOG.fine(tag + "[ScreenContentDetector] unnumbered: no cursor glyph found");
            return Optional.empty();
        }

        // Step 4: find header — walk upward from stopRow past search box / box-drawing lines
        String header = "";
        if (stopRow >= 0) {
            for (int h = stopRow; h >= 0; h--) {
                String line = screenLines.get(h).trim();
                if (line.isBlank() || isSeparatorLine(line) || isBoxDrawingLine(line)
                        || line.contains("\u2315")) {
                    continue;
                }
                // First non-blank, non-separator, non-box line above the options region
                header = line;
                break;
            }
        }

        LOG.fine(tag + "[ScreenContentDetector] unnumbered menu: header=\"" + header
                + "\" options=" + options + " defaultIdx=" + defaultIdx);
        return Optional.of(new ChoiceMenuModel(header, options, defaultIdx));
    }

public static void open(
            String filePath, String before, String after, String tabName,
            String hookCwd,
            Runnable onAccept,
            Consumer<String> onDecline,
            Runnable onCancel,
            Runnable onClose) {

        SwingUtilities.invokeLater(() -> {
            // Look up the session tab first so its startup dir can be used as the project root.
            // hookCwd != null (hook case): match tab whose startup dir is an ancestor of hookCwd.
            //   Claude may have cd'd into a subdirectory; the tab was opened at the project root.
            // hookCwd == null (MCP case): match tab whose startup dir contains filePath.
            final ClaudeSessionTab sessionTab = WindowManager.getDefault().getRegistry().getOpened().stream()
                    .map(tc -> {
                        if (!(tc instanceof ClaudeSessionTab s)) return null;
                        File dir = s.getWorkingDirectory();
                        if (dir == null) return null;
                        String abs = dir.getAbsolutePath();
                        return (hookCwd != null ? isFileUnderDirectory(hookCwd, abs)
                                : isFileUnderDirectory(filePath, abs)) ? s : null;
                    })
                    .filter(Objects::nonNull)
                    .findFirst()
                    .orElse(null);

            // Determine if the file is outside the relevant project directory.
            // hookCwd != null (hook): use the session tab's startup dir as the project root
            //   (falls back to hookCwd if no tab found).
            // hookCwd == null (MCP): check against all open sessions.
            final boolean outsideProject;
            final String outsideWarning;
            if (hookCwd != null) {
                String projectRoot = (sessionTab != null && sessionTab.getWorkingDirectory() != null)
                        ? sessionTab.getWorkingDirectory().getAbsolutePath()
                        : hookCwd;
                outsideProject = !isFileUnderDirectory(filePath, projectRoot);
                outsideWarning = "⚠ This file is outside the current project";
            } else {
                boolean insideAny = false;
                for (TopComponent tc : WindowManager.getDefault().getRegistry().getOpened()) {
                    if (tc instanceof ClaudeSessionTab stc) {
                        java.io.File dir = stc.getWorkingDirectory();
                        if (dir != null && isFileUnderDirectory(filePath, dir.getAbsolutePath())) {
                            insideAny = true;
                            break;
                        }
                    }
                }
                outsideProject = !insideAny;
                outsideWarning = "⚠ This file is outside any open project";
            }

            Diff diffService = Lookup.getDefault().lookup(Diff.class);
            if (diffService == null) {
                LOGGER.warning("Diff service not available; falling back to onClose for: " + tabName);
                onClose.run();
                activateSessionForFile(filePath);
                return;
            }

            String fileName = new java.io.File(filePath).getName();
            StreamSource oldSource = textSource(fileName + " (before)", filePath, before);
            StreamSource newSource = textSource(fileName + " (after)",  filePath, after);

            final DiffView diffView;
            try {
                diffView = diffService.createDiff(oldSource, newSource);
            } catch (IOException e) {
                LOGGER.log(Level.WARNING, "Error creating diff view for: " + tabName, e);
                onClose.run();
                activateSessionForFile(filePath);
                return;
            }

            if (diffView == null) {
                LOGGER.warning("createDiff returned null; falling back to onClose for: " + tabName);
                onClose.run();
                activateSessionForFile(filePath);
                return;
            }

            // Flag set to true once a button is clicked — prevents onClose from
            // firing again when the diff is closed.
            AtomicBoolean decided = new AtomicBoolean(false);

            String workingDir = sessionTab != null && sessionTab.getWorkingDirectory() != null
                    ? sessionTab.getWorkingDirectory().getAbsolutePath()
                    : null;

            // Forward reference for the close action (resolved below for each branch).
            Runnable[] closeDiffRef = { null };

            FileDiffPermissionPanel permPanel = new FileDiffPermissionPanel(
                () -> {
                    decided.set(true);
                    onAccept.run();
                    closeDiffRef[0].run();
                    activateSessionForFile(filePath);
                },
                reason -> {
                    decided.set(true);
                    onDecline.accept(reason);
                    closeDiffRef[0].run();
                    activateSessionForFile(filePath);
                },
                sessionTab == null ? null : () -> {
                    sessionTab.setEditMode(EditMode.ACCEPT_EDITS);
                    decided.set(true);
                    onAccept.run();
                    closeDiffRef[0].run();
                    activateSessionForFile(filePath);
                },
                sessionTab == null ? null : () -> {
                    decided.set(true);
                    onCancel.run();
                    closeDiffRef[0].run();
                    activateSessionForFile(filePath);
                },
                workingDir
            );

            boolean isMdFile = filePath.toLowerCase().endsWith(".md")
                    || filePath.toLowerCase().endsWith(".markdown");
            LOGGER.fine("FileDiffOpener.open: isMdFile=" + isMdFile + " filePath=" + filePath);

            // Keep the DiffView's own navigation toolbar (prev/next difference buttons)
            // Null means this DiffView provider offers no toolbar — don't add an empty one.
            JToolBar toolbar = diffView.getToolBar();

            // One-element arrays for mutable references captured by lambdas
            final MarkdownDiffPanel[] mdPanelRef = { null };
            final javax.swing.JSplitPane[] mdSplitRef = { null };
            // Persists the vertical divider position across hide/show within this session
            final int[] savedVertDivider = { -1 };

            // Build the wrapper panel that holds either the raw diff or the MD split
            java.awt.Component initialContent = diffView.getComponent();
            MdPreviewInDiffMode previewMode = ClaudeCodePreferences.getMdPreviewInDiffMode();
            boolean showMdPreview = isMdFile && switch (previewMode) {
                case ALWAYS      -> true;
                case NEVER       -> false;
                case EXCEPT_PLAN -> {
                    // Suppress for plan files when a dedicated tab will open (autoPlanPreview)
                    // or already is open for this exact file.
                    Path parent = Path.of(filePath).getParent();
                    boolean isPlanFile = parent != null
                            && "plans".equals(parent.getFileName().toString());
                    yield !(isPlanFile && (ClaudeCodePreferences.isAutoPlanPreview()
                            || MarkdownPreviewTab.isTabOpenFor(filePath)));
                }
            };
            if (showMdPreview) {
                MarkdownDiffPanel mdPanel = new MarkdownDiffPanel(before, after);
                mdPanel.attachRawDiffSync(diffView.getComponent());
                javax.swing.JSplitPane mdSplit = new javax.swing.JSplitPane(
                        javax.swing.JSplitPane.VERTICAL_SPLIT, mdPanel, diffView.getComponent());
                mdSplit.setResizeWeight(0.5);
                mdPanelRef[0] = mdPanel;
                mdSplitRef[0] = mdSplit;
                initialContent = mdSplit;
                // Restore saved divider position after initial layout
                int savedDiv = loadDividerPref();
                SwingUtilities.invokeLater(() -> {
                    if (savedDiv >= 0) {
                        mdSplit.setDividerLocation(savedDiv);
                    }
                    // else let resizeWeight(0.5) handle default
                });
                // Auto-save on user drag
                mdSplit.addPropertyChangeListener(javax.swing.JSplitPane.DIVIDER_LOCATION_PROPERTY, e -> {
                    int loc = mdSplit.getDividerLocation();
                    int h   = mdSplit.getHeight();
                    if (h > 0 && loc > 0 && loc < h) {
                        savedVertDivider[0] = loc;
                        saveDividerPref(loc);
                    }
                });
            }

            final javax.swing.JPanel wrapperPanel =
                    new javax.swing.JPanel(new java.awt.BorderLayout());
            wrapperPanel.add(initialContent, java.awt.BorderLayout.CENTER);

            // "Preview Markdown" checkbox item (only for .md files)
            final JCheckBoxMenuItem[] previewItemRef = { null };
            // Idempotent cleanup: removes the AWTEventListener once, then becomes a no-op.
            final Runnable[] removeAwtListener = { null };
            removeAwtListener[0] = () -> {};
            if (isMdFile) {
                JCheckBoxMenuItem previewItem =
                        new JCheckBoxMenuItem("Preview Markdown");
                previewItem.setSelected(showMdPreview);
                previewItemRef[0] = previewItem;

                previewItem.addActionListener(e ->
                    toggleMdPreview(previewItem.isSelected(), before, after,
                            diffView, wrapperPanel, mdPanelRef, mdSplitRef,
                            filePath, previewItemRef, savedVertDivider));

                java.awt.Component diffComp = diffView.getComponent();
                // We need to inject "Preview Markdown" into the right-click popup that NetBeans'
                // diff component shows natively. PopupMenuListener cannot be used because
                // JPopupMenu.COMPONENT_SHOWN never fires for this component. Instead we listen
                // for the popup-trigger mouse event via AWTEventListener (which fires before the
                // popup is built) and schedule the injection via two nested invokeLater calls:
                //   - first invokeLater: runs after the current event is fully dispatched (popup is shown)
                //   - second invokeLater: runs one more EDT cycle later, by which time
                //     MenuSelectionManager has registered the popup in its selected path
                //     (getSelectedPath() returns non-empty)
                // A single invokeLater is not enough — getSelectedPath() still returns [] on the
                // first cycle.
                java.awt.event.AWTEventListener awtL = awtEvent -> {
                    if (!(awtEvent instanceof java.awt.event.MouseEvent me) || !me.isPopupTrigger()) return;
                    java.awt.Component src = me.getComponent();
                    if (src == null || !SwingUtilities.isDescendingFrom(src, diffComp)) return;
                    SwingUtilities.invokeLater(() -> SwingUtilities.invokeLater(() -> {
                        for (javax.swing.MenuElement el :
                                javax.swing.MenuSelectionManager.defaultManager().getSelectedPath()) {
                            if (el instanceof JPopupMenu menu) {
                                addPreviewItemToPopup(menu, previewItem);
                                break;
                            }
                        }
                    }));
                };
                java.awt.Toolkit.getDefaultToolkit().addAWTEventListener(
                        awtL, java.awt.AWTEvent.MOUSE_EVENT_MASK);
                removeAwtListener[0] = () -> {
                    removeAwtListener[0] = () -> {};
                    java.awt.Toolkit.getDefaultToolkit().removeAWTEventListener(awtL);
                };
            }

            // Wire MarkdownDiffPanel callbacks
            if (isMdFile && mdPanelRef[0] != null) {
                mdPanelRef[0].setOnHide(() -> {
                    if (previewItemRef[0] != null) previewItemRef[0].setSelected(false);
                    toggleMdPreview(false, before, after,
                            diffView, wrapperPanel, mdPanelRef, mdSplitRef,
                            filePath, previewItemRef, savedVertDivider);
                });
                mdPanelRef[0].setOnPinPreview(() ->
                        MarkdownPreviewTab.openLive(filePath, after,
                                org.openide.filesystems.FileUtil.toFileObject(new java.io.File(filePath))));
            }

            // --- SESSION branch ---
            if (!ClaudeCodePreferences.isOpenDiffInSeparateTab()
                    && sessionTab != null) {
                closeDiffRef[0] = sessionTab::hideEmbeddedDiff;
                closeDiffRef[0] = withCleanup(closeDiffRef[0], removeAwtListener);
                boolean shown = sessionTab.showEmbeddedDiff(
                        outsideProject, outsideWarning,
                        toolbar, wrapperPanel, permPanel,
                        () -> { removeAwtListener[0].run(); if (!decided.get()) { onClose.run(); activateSessionForFile(filePath); } });
                if (shown) return;
            }

            // --- TOPLEVEL branch ---
            TopComponent diffTC = new DiffTopComponent(removeAwtListener, decided, onClose, filePath);
            closeDiffRef[0] = diffTC::close;
            diffTC.setDisplayName(tabName);
            diffTC.setLayout(new java.awt.BorderLayout());

            if (toolbar != null) {
                toolbar.setFloatable(false);
                diffTC.add(toolbar, java.awt.BorderLayout.NORTH);
            }
            diffTC.add(wrapperPanel, java.awt.BorderLayout.CENTER);
            if (outsideProject) {
                permPanel.showWarning(outsideWarning);
            }
            diffTC.add(permPanel, java.awt.BorderLayout.SOUTH);

            io.github.nbplugins.claudecodegui.ui.common.UiUtils.dockAndOpen(
                    diffTC, ClaudeCodePreferences.getFileDiffDockMode());
            diffTC.requestActive();
            SwingUtilities.invokeLater(permPanel::requestAcceptFocus);
        });
    }
